"use strict";(globalThis.webpackChunkmy_website=globalThis.webpackChunkmy_website||[]).push([[993],{5091(e,t,a){a.r(t),a.d(t,{assets:()=>l,contentTitle:()=>s,default:()=>u,frontMatter:()=>r,metadata:()=>o,toc:()=>c});var o=a(2029),n=a(4848),i=a(8453);const r={slug:"computercraft-os",title:"Building a Unix-like OS for ComputerCraft",authors:["william"],tags:["softwaredev"]},s=void 0,l={authorsImageUrls:[void 0]},c=[];function d(e){const t={a:"a",img:"img",p:"p",...(0,i.R)(),...e.components},{ImageCaption:o}=t;return o||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("ImageCaption",!0),(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.p,{children:"Around a year ago I began working on building an operating system for ComputerCraft. It started when I noticed the complete lack of security features in ComputerCraft, and evolved into a months-long lesson about the architecture of Linux/Unix."}),"\n",(0,n.jsxs)(t.p,{children:[(0,n.jsx)(t.img,{alt:"Installing Hecate on a ComputerCraft computer, booting it, and running ls and cd",src:a(2477).A+"",width:"960",height:"613"}),"\n",(0,n.jsx)(o,{children:"Installing v0.1.0-alpha.2 with wget, then booting into the Hecate shell."})]}),"\n",(0,n.jsx)(t.p,{children:"For those that don't know, ComputerCraft is a mod for Minecraft that adds Lua-powered computers to the game. The computers can interact with the world in various ways, and there are \"turtle\" computers that can even move around and break blocks. The mod is used in a variety of ways, sometimes to create massive quarries utilizing the turtles, or in combination with other mods to act as an control system or custom dashboard for advanced automation. It's a very powerful mod in all respects, but it has one major flaw - it lacks security."}),"\n",(0,n.jsx)(t.p,{children:"ComputerCraft computers ship with a very basic single-user operating system that lacks any access-control features. If you can interact with a computer, you can run any program, edit any file, or even just delete everything. There are no systems in place to prevent a bad actor from accessing your computer and doing anything they want with it. In single-player this is fine, but in multiplayer it could lead to an issue. So I decided I wanted to try and solve it."}),"\n",(0,n.jsx)(t.p,{children:"From the beginning I knew I wanted to take strong cues from Unix. I daily-drive Arch Linux on my laptop so I was already somewhat familiar with its security model, but the project started off more as a sandbox than a full operating system. It ran at startup and modified the global environment, redirecting file access through its own functions that enforced access control rules. It used a layer over ComputerCraft's base filesystem, with a .inode and .dentry file that defined the owner, read, write, execute, and more for each file."}),"\n",(0,n.jsx)(t.p,{children:"Eventually though, the plans grew beyond just a sandbox for user programs. I kept wanting to learn more about the architecture of Linux, and I kept running into limitations with the sandbox model. I restarted the project (for the first time, I'll talk about the second time in a future blog post) and wrote it from the start with the goal of it being a full OS. Not only has this unlocked a lot more potential for security features, it also now runs in plain lua, not just ComputerCraft, and it has expanded my knowledge of how Linux works. I've learned a lot about drivers and devices, the virtual file system, the user- and kernel-space divide, and more."}),"\n",(0,n.jsx)(t.p,{children:"Now I'm getting closer to the first release version of the project. After 2 full rewrites and nearly a year of development, it has a working VFS and permissions, a driver and device system, a scheduler, a few userland utilities, and more. For now I've put out v0.1.0-alpha.2 on my GitHub, but before the full v0.1.0 release I want to add some more userland utilities and fix up some bugs that are still left in the code. Beyond v0.1.0 I still have lots of ideas for topics to explore, including pipes, block devices, proper authentication, and more."}),"\n",(0,n.jsx)(t.p,{children:"It's still not yet a security upgrade over the base ComputerCraft OS, but the framework is there and I'll be able to build on it now that I've mostly locked down the design. Once authentication and protection from just killing the OS is implemented, it will definitely be a step up, but there's always the risk of someone having physical access to the computer."}),"\n",(0,n.jsxs)(t.p,{children:["The source code is available on ",(0,n.jsx)(t.a,{href:"https://github.com/self-init/hecate",children:"GitHub"})," and you can find ",(0,n.jsx)(t.a,{href:"https://github.com/self-init/hecate/releases/tag/v0.1.0-alpha.2",children:"v0.1.0-alpha.2"})," on the releases page. Make sure to check the readme for instructions on how to install or run it."]}),"\n",(0,n.jsxs)(t.p,{children:["Update: ",(0,n.jsx)(t.a,{href:"https://github.com/self-init/hecate/releases/tag/v0.1.0",children:"v0.1.0"})," is released! Go check it out!"]})]})}function u(e={}){const{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(d,{...e})}):d(e)}},2477(e,t,a){a.d(t,{A:()=>o});const o=a.p+"assets/images/hecate-960-0b0c67964a79ca099b7b3fae67cc4aec.gif"},8453(e,t,a){a.d(t,{R:()=>r,x:()=>s});var o=a(6540);const n={},i=o.createContext(n);function r(e){const t=o.useContext(i);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:r(e.components),o.createElement(i.Provider,{value:t},e.children)}},2029(e){e.exports=JSON.parse('{"permalink":"/blog/computercraft-os","source":"@site/blog/2026-10-22-computercraft-os/index.md","title":"Building a Unix-like OS for ComputerCraft","description":"Around a year ago I began working on building an operating system for ComputerCraft. It started when I noticed the complete lack of security features in ComputerCraft, and evolved into a months-long lesson about the architecture of Linux/Unix.","date":"2026-10-22T00:00:00.000Z","tags":[{"inline":false,"label":"Software Dev","permalink":"/blog/tags/softwaredev","description":"Posts related to software development"}],"readingTime":3.44,"hasTruncateMarker":true,"authors":[{"name":"William Anderson","url":"https://linkedin.com/in/william-anderson-cyber","page":{"permalink":"/blog/authors/william"},"socials":{"linkedin":"https://www.linkedin.com/in/william-anderson-cyber/","github":"https://github.com/self-init","email":"mailto:me@williamanderson.dev"},"imageURL":"/img/myface.jpg","key":"william"}],"frontMatter":{"slug":"computercraft-os","title":"Building a Unix-like OS for ComputerCraft","authors":["william"],"tags":["softwaredev"]},"unlisted":false,"nextItem":{"title":"Designing A Home Cyber Lab","permalink":"/blog/homelab-setup"}}')}}]);